38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Fixed city-to-region table used to derive {@link #getLocality() locality}. Any city not
71	     * listed derives the locality {@code 'UNKNOWN'}.
72	     */
73	    private static final Map<String, String> CITY_REGION = Map.of(
74	        "Sydney", "NSW",
75	        "Melbourne", "VIC",
76	        "Brisbane", "QLD");
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    /**
127	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
128	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). Derived
129	     * from the owner's own customer code and registration date; {@code null} when either is absent.
130	     *
131	     * @return the membership number, or {@code null} when it cannot be derived
132	     */
133	    public String getMembershipNumber() {
134	        if (this.customerCode == null || this.registrationDate == null) {
135	            return null;
136	        }
137	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
138	    }
139	
140	    /**
141	     * The owner's membership tier, derived from the namesake count and email. Returns
142	     * {@code 'SILVER'} when the owner has no namesakes ({@code namesakeCount} is 0) and an
143	     * email address is present; otherwise {@code 'BRONZE'}.
144	     *
145	     * @return the membership tier, either {@code 'SILVER'} or {@code 'BRONZE'}
146	     */
147	    public String getMembershipTier() {
148	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
149	        boolean hasEmail = this.email != null && !this.email.isBlank();
150	        return hasNoNamesakes && hasEmail ? "SILVER" : "BRONZE";
151	    }
152	
153	    /**
154	     * The owner's locality, derived from the {@link #getCity() city} using the fixed
155	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical
156	     * region string, or {@code 'UNKNOWN'} when the city is absent or not in the table.
157	     *
158	     * @return the canonical region string, or {@code 'UNKNOWN'}
159	     */
160	    public String getLocality() {
161	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
162	    }
163	
164	    public String getHouseholdId() {
165	        return this.householdId;
166	    }
167	
168	    public void setHouseholdId(String householdId) {
169	        this.householdId = householdId;
170	    }
171	
172	    public Integer getNamesakeCount() {
173	        return this.namesakeCount;
174	    }
175	
176	    public void setNamesakeCount(Integer namesakeCount) {
177	        this.namesakeCount = namesakeCount;
178	    }
179	
180	    /**
181	     * Defaults the registration date to the server's current date when none was supplied,
182	     * so every newly persisted owner is stamped exactly once on insert, then rolls the
183	     * effective date forward to a business day so no owner is ever registered on a weekend.
184	     */
185	    @PrePersist
186	    void onCreate() {
187	        if (this.registrationDate == null) {
188	            this.registrationDate = LocalDate.now();
189	        }
190	        this.registrationDate = toBusinessDay(this.registrationDate);
191	    }
192	
193	    /**
194	     * Rolls a registration date forward onto a business day: a Saturday or Sunday becomes the
195	     * following Monday, while any weekday is returned unchanged. This is the single definition of
196	     * the business-day rule, applied to the effective registration date whether it was supplied in
197	     * the request or defaulted to the server's current date.
198	     *
199	     * @param date the effective registration date
200	     * @return the date itself when it is a weekday, otherwise the next Monday
201	     */
202	    public static LocalDate toBusinessDay(LocalDate date) {
203	        return switch (date.getDayOfWeek()) {
204	            case SATURDAY -> date.plusDays(2);
205	            case SUNDAY -> date.plusDays(1);
206	            default -> date;
207	        };
208	    }
209	
210	    protected Set<Pet> getPetsInternal() {
211	        if (this.pets == null) {
212	            this.pets = new HashSet<>();
213	        }
214	        return this.pets;
215	    }
216	
217	    protected void setPetsInternal(Set<Pet> pets) {
218	        this.pets = pets;
219	    }
220	
221	    public List<Pet> getPets() {
222	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
223	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
224	        return Collections.unmodifiableList(sortedPets);
225	    }
226	
227	    public void setPets(List<Pet> pets) {
228	        this.pets = new HashSet<>(pets);
229	    }
230	
231	    public void addPet(Pet pet) {
232	        getPetsInternal().add(pet);
233	        pet.setOwner(this);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name) {
243	        return getPet(name, false);
244	    }
245	
246	    /**
247	     * Return the Pet with the given name, or null if none found for this Owner.
248	     *
249	     * @param name to test
250	     * @return true if pet name is already in use
251	     */
252	    public Pet getPet(String name, boolean ignoreNew) {
253	        name = name.toLowerCase();
254	        for (Pet pet : getPetsInternal()) {
255	            if (!ignoreNew || !pet.isNew()) {
256	                String compName = pet.getName();
257	                compName = compName.toLowerCase();
258	                if (compName.equals(name)) {
259	                    return pet;
260	                }
261	            }
262	        }
263	        return null;
264	    }
265	
266	    public Pet getPet(Integer petId) {
267	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
268	    }
269	
270	    @Override
271	    public String toString() {
272	        return new ToStringCreator(this)
273	
274	            .append("id", this.getId())
275	            .append("new", this.isNew())
276	            .append("lastName", this.getLastName())
277	            .append("firstName", this.getFirstName())
278	            .append("address", this.address)
279	            .append("city", this.city)
280	            .append("telephone", this.telephone)
281	            .toString();
282	    }
283	}
