63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    /**
79	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
80	     * and a domain containing at least one dot, with no whitespace in any segment.
81	     */
82	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
86	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * Maximum number of owners that may be registered on a single day (by registration date). A create
92	     * attempted once this many owners already carry today's registration date is rejected with a
93	     * 429 Too Many Requests.
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /**
98	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
99	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
100	     */
101	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
102	        "ST", "STREET",
103	        "RD", "ROAD",
104	        "AVE", "AVENUE");
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        LocalDate registrationDate = Owner.toBusinessDay(
148	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
149	        owner.setRegistrationDate(registrationDate);
150	        requireDailyCapacity(registrationDate);
151	        requireCityHasCapacity(owner.getCity());
152	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
153	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
154	            joinHousehold(owner);
155	        } else {
156	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
157	        }
158	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
159	        requireUniqueTelephone(telephone);
160	        owner.setTelephone(telephone);
161	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
162	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        this.clinicService.saveOwner(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    /**
172	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
173	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
174	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
175	     * existed prior to this create.
176	     *
177	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
178	     *     a business day
179	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
180	     *     registered on that business day
181	     */
182	    private void requireDailyCapacity(LocalDate registrationDate) {
183	        long dayOwnerCount = this.clinicService.findAllOwners().stream()
184	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
185	            .count();
186	        if (dayOwnerCount >= MAX_OWNERS_PER_DAY) {
187	            throw new DailyOwnerLimitException(registrationDate);
188	        }
189	    }
190	
191	    /**
192	     * Rejects an owner whose city already contains the maximum allowed number of owners
193	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
194	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
195	     * create.
196	     *
197	     * @param city the city of the owner being created
198	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
199	     */
200	    private void requireCityHasCapacity(String city) {
201	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
203	            .count();
204	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
205	            throw new CityOwnerLimitException(city);
206	        }
207	    }
208	
209	    /**
210	     * Generates the customer code for a newly created owner, formatted
211	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
212	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
213	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
214	     * that city (e.g. {@code 'LON-SMI-0007'}).
215	     *
216	     * @param city the owner's city
217	     * @param lastName the owner's last name
218	     * @return the generated customer code
219	     */
220	    private String generateCustomerCode(String city, String lastName) {
221	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
222	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
223	        int sequence = (int) this.clinicService.findAllOwners().stream()
224	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
225	            .count() + 1;
226	        return String.format("%s-%s-%04d", city3, last3, sequence);
227	    }
228	
229	    /**
230	     * Counts the existing owners that already share the given first name and last name, compared
231	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
232	     * owners that existed prior to this create.
233	     *
234	     * @param firstName the first name of the owner being created
235	     * @param lastName the last name of the owner being created
236	     * @return the number of pre-existing namesakes
237	     */
238	    private int countNamesakes(String firstName, String lastName) {
239	        return (int) this.clinicService.findAllOwners().stream()
240	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
241	                && equalsIgnoreCase(existing.getLastName(), lastName))
242	            .count();
243	    }
244	
245	    /**
246	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
247	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
248	     *
249	     * @param a the first value, possibly {@code null}
250	     * @param b the second value, possibly {@code null}
251	     * @return whether the values are equal ignoring case
252	     */
253	    private boolean equalsIgnoreCase(String a, String b) {
254	        return a == null ? b == null : a.equalsIgnoreCase(b);
255	    }
256	
257	    /**
258	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
259	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
260	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
261	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
262	     *
263	     * @param ownerFieldsDto the submitted owner fields
264	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
265	     */
266	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
267	        List<String> invalidFields = new ArrayList<>();
268	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
269	            invalidFields.add("firstName");
270	        }
271	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
272	            invalidFields.add("lastName");
273	        }
274	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
275	            invalidFields.add("address");
276	        }
277	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
278	            invalidFields.add("city");
279	        }
280	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
281	            invalidFields.add("telephone");
282	        }
283	        if (!invalidFields.isEmpty()) {
284	            throw new InvalidOwnerFieldsException(invalidFields);
285	        }
286	    }
287	
288	    /**
289	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
290	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
291	     * what gets stored and returned.
292	     *
293	     * @param telephone the raw telephone value from the request
294	     * @return the normalized E.164 telephone number
295	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
296	     */
297	    private String normalizeTelephone(String telephone) {
298	        String e164 = toE164(telephone);
299	        if (e164 == null) {
300	            throw new InvalidOwnerFieldsException(List.of("telephone"));
301	        }
302	        return e164;
303	    }
304	
305	    /**
306	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
307	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
308	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
309	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
310	     * it contains 8 to 15 digits after the {@code '+'}.
311	     *
312	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
313	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
314	     *
315	     * @param telephone the raw telephone value, possibly {@code null}
316	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
317	     */
318	    private String toE164(String telephone) {
319	        if (telephone == null) {
320	            return null;
321	        }
322	        String cleaned = telephone.replaceAll("[ \\-()]", "");
323	        String digits;
324	        if (cleaned.startsWith("+")) {
325	            digits = cleaned.substring(1);
326	        } else {
327	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
328	            digits = "61" + national;
329	        }
330	        if (!digits.matches("[0-9]{8,15}")) {
331	            return null;
332	        }
333	        return "+" + digits;
334	    }
335	
336	    /**
337	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
338	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
339	     * and returned lower-cased.
340	     *
341	     * @param email the raw email value from the request, possibly {@code null}
342	     * @return the lower-cased email, or {@code null} when none was supplied
343	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
344	     */
345	    private String normalizeEmail(String email) {
346	        if (!StringUtils.hasText(email)) {
347	            return null;
348	        }
349	        String trimmed = email.trim();
350	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
351	            throw new InvalidOwnerFieldsException(List.of("email"));
352	        }
353	        return trimmed.toLowerCase(Locale.ROOT);
354	    }
355	
356	    /**
357	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
358	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
359	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
360	     *
361	     * @param telephone the normalized (E.164) telephone of the owner being created
362	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
363	     */
364	    private void requireUniqueTelephone(String telephone) {
365	        boolean inUse = this.clinicService.findAllOwners().stream()
366	            .map(Owner::getTelephone)
367	            .filter(existing -> existing != null)
368	            .map(existing -> {
369	                String e164 = toE164(existing);
370	                return e164 != null ? e164 : existing;
371	            })
372	            .anyMatch(telephone::equals);
373	        if (inUse) {
374	            throw new DuplicateTelephoneException(telephone);
375	        }
376	    }
377	
378	    /**
379	     * Rejects an owner whose last name and address match those of an existing owner, where both are
380	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
381	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
382	     *
383	     * @param lastName the last name of the owner being created
384	     * @param address the address of the owner being created
385	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
386	     */
387	    private void requireUniqueHousehold(String lastName, String address) {
388	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
389	            throw new DuplicateHouseholdException(lastName, address);
390	        }
391	    }
392	
393	    /**
394	     * Returns the existing owners that belong to the same household as the given last name and
395	     * address, i.e. those whose last name and address match case-insensitively and with runs of
396	     * whitespace collapsed to a single space.
397	     *
398	     * @param lastName the last name to match
399	     * @param address the address to match
400	     * @return the matching owners (possibly empty, never {@code null})
401	     */
402	    private List<Owner> findHouseholdMembers(String lastName, String address) {
403	        String normalizedLastName = normalizeForHousehold(lastName);
404	        String normalizedAddress = normalizeAddress(address);
405	        return this.clinicService.findAllOwners().stream()
406	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
407	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
408	            .toList();
409	    }
410	
411	    /**
412	     * Joins the owner being created to the shared household of any existing owner(s) that have the
413	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
414	     * member of the household - the existing owners and the new one - is assigned the same stable
415	     * {@code householdId}, so the shared identifier can be read back from any of them.
416	     *
417	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
418	     * the owner is left without a {@code householdId}.
419	     *
420	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
421	     */
422	    private void joinHousehold(Owner owner) {
423	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
424	        if (members.isEmpty()) {
425	            return;
426	        }
427	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
428	        owner.setHouseholdId(householdId);
429	        for (Owner member : members) {
430	            if (!householdId.equals(member.getHouseholdId())) {
431	                member.setHouseholdId(householdId);
432	                this.clinicService.saveOwner(member);
433	            }
434	        }
435	    }
436	
437	    /**
438	     * Computes the stable, shared household identifier for a last name and address. The value is
439	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
440	     * name and address, so every owner in the same household computes the same identifier.
441	     *
442	     * @param lastName the last name of the household
443	     * @param address the address of the household
444	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
445	     */
446	    private String computeHouseholdId(String lastName, String address) {
447	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
448	        try {
449	            byte[] digest = MessageDigest.getInstance("SHA-256")
450	                .digest(key.getBytes(StandardCharsets.UTF_8));
451	            StringBuilder hex = new StringBuilder();
452	            for (int i = 0; i < 6; i++) {
453	                hex.append(String.format("%02X", digest[i]));
454	            }
455	            return "HH-" + hex;
456	        } catch (NoSuchAlgorithmException e) {
457	            throw new IllegalStateException("SHA-256 algorithm not available", e);
458	        }
459	    }
460	
461	    /**
462	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
463	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
464	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
465	     *
466	     * @param value the raw value, possibly {@code null}
467	     * @return the normalized value
468	     */
469	    private String normalizeForHousehold(String value) {
470	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
471	    }
472	
473	    /**
474	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
475	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
476	     * value yields an empty string.
477	     *
478	     * @param value the raw value, possibly {@code null}
479	     * @return the trimmed, whitespace-collapsed value
480	     */
481	    private String collapseWhitespace(String value) {
482	        if (value == null) {
483	            return "";
484	        }
485	        return value.trim().replaceAll("\\s+", " ");
486	    }
487	
488	    /**
489	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
490	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
491	     * is upper-cased, and common street-type abbreviations are expanded as whole words
492	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
493	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
494	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
495	     *
496	     * @param address the raw address value, possibly {@code null}
497	     * @return the normalized address
498	     */
499	    private String normalizeAddress(String address) {
500	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
501	        if (collapsed.isEmpty()) {
502	            return "";
503	        }
504	        String[] tokens = collapsed.split(" ");
505	        StringBuilder normalized = new StringBuilder();
506	        for (int i = 0; i < tokens.length; i++) {
507	            if (i > 0) {
508	                normalized.append(' ');
509	            }
510	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
511	        }
512	        return normalized.toString();
513	    }
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
518	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
519	        if (currentOwner == null) {
520	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
521	        }
522	        currentOwner.setAddress(ownerFieldsDto.getAddress());
523	        currentOwner.setCity(ownerFieldsDto.getCity());
524	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
525	        currentOwner.setLastName(ownerFieldsDto.getLastName());
526	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
527	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
528	        this.clinicService.saveOwner(currentOwner);
529	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
530	    }
531	
532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Transactional
534	    @Override
535	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
536	        Owner owner = this.clinicService.findOwnerById(ownerId);
537	        if (owner == null) {
538	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
539	        }
540	        this.clinicService.deleteOwner(owner);
541	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
542	    }
543	
544	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
545	    @Override
546	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
547	        Owner owner = this.clinicService.findOwnerById(ownerId);
548	        if (owner == null) {
549	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
550	        }
551	        HttpHeaders headers = new HttpHeaders();
552	        Pet pet = petMapper.toPet(petFieldsDto);
553	        owner.setId(ownerId);
554	        pet.setOwner(owner);
555	        pet.getType().setName(null);
556	        this.clinicService.savePet(pet);
557	        PetDto petDto = petMapper.toPetDto(pet);
558	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
559	            .buildAndExpand(pet.getId()).toUri());
560	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
561	    }
562	
563	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
564	    @Override
565	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
566	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
567	        if (currentOwner != null) {
568	            Pet currentPet = this.clinicService.findPetById(petId);
569	            if (currentPet != null) {
570	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
571	                currentPet.setName(petFieldsDto.getName());
572	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
573	                this.clinicService.savePet(currentPet);
574	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
575	            }
576	        }
577	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
578	    }
579	
580	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
581	    @Override
582	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
583	        HttpHeaders headers = new HttpHeaders();
584	        Visit visit = visitMapper.toVisit(visitFieldsDto);
585	        Pet pet = new Pet();
586	        pet.setId(petId);
587	        visit.setPet(pet);
588	        this.clinicService.saveVisit(visit);
589	        VisitDto visitDto = visitMapper.toVisitDto(visit);
590	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
591	            .buildAndExpand(visit.getId()).toUri());
592	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
593	    }
594	
595	
596	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
597	    @Override
598	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
599	        Owner owner = this.clinicService.findOwnerById(ownerId);
600	        if (owner != null) {
601	            Pet pet = owner.getPet(petId);
602	            if (pet != null) {
603	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
604	            }
605	        }
606	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
607	    }
608	}
